class FEMenuEntry {
public:
    int entry_num;
    FEMenuEntry *next;
    virtual void Draw();
};

class PanelQuad {
public:
    virtual void TurnOn(bool);
};

class BoxText {
public:
    virtual void Draw();
};

struct MemCard {
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};

class NamesMenu {
    char pad00[0x38];
    int max_vis_entries;
    char pad3c[0x44 - 0x3c];
    FEMenuEntry *first_vis_entry;
    char pad48[0x4c - 0x48];
    FEMenuEntry *highlighted;
    char pad50[0x178 - 0x50];
    int arrow_num;
    int arrow_counter;
    char pad180[0x1bc - 0x180];
    MemCard cards[2];
    char pad1dc[0x200 - 0x1dc];
    int adjusted_active_card;
    char pad204[0x208 - 0x204];
    PanelQuad *box;
    PanelQuad *arrows[2][2];
    PanelQuad *lines[10];
    PanelQuad *top_line;
    PanelQuad *side_line;
    FEMenuEntry *entry[17];
    BoxText *message;
    BoxText *freeSpace;
    char pad298[0x2a4 - 0x298];
    bool draw_message;

public:
    void Draw();
};

void NamesMenu::Draw()
{
    if(arrow_counter >= 0) arrow_counter--;
    if(arrow_counter < 0 && arrow_counter > -5)
    {
        arrow_counter = -5;
        arrows[0][0]->TurnOn(true);
        arrows[0][1]->TurnOn(false);
        arrows[1][0]->TurnOn(true);
        arrows[1][1]->TurnOn(false);
    }

    if (cards[adjusted_active_card].exists && cards[adjusted_active_card].available)
    {
#ifndef TARGET_PS2
        freeSpace->Draw();
#endif
    }
    highlighted->Draw();
    if(!draw_message)
    {
        FEMenuEntry* tmp = first_vis_entry;
        for(int i=0; i<max_vis_entries; i++)
        {
            tmp->Draw();
            tmp = tmp->next;
        }
    }
    else message->Draw();
}
